def main():
    n = int(input())
    a = list(map(int, input().split()))
    seen = set()
    out = []
    for x in a:
        if x not in seen:
            seen.add(x)
            out.append(x)
    print(*out)

def main():
    s = input().strip()
    st = []
    pair = {")": "(", "]": "[", "}": "{"}
    for ch in s:
        if ch in "([{":
            st.append(ch)
        elif not st or st.pop() != pair[ch]:
            print("BAD")
            return
    print("OK" if not st else "BAD")

def main():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    c = 0
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += a[j]
            if s == k:
                c += 1
    print(c)
